import com.webcommander.sdk.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.taxSettings().getTaxSettings();
Map<?, ?> taxSettings = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("tax_settings");
System.out.println(taxSettings.get("default_country") + " " + taxSettings.get("default_tax_code"));
System.out.println(taxSettings.get("tax_message"));

